function buildLPS(pattern){
  const m=pattern.length,lps=new Array(m).fill(0);
  let l=0,r=1;
  while(r<m){if(pattern[r]===pattern[l]){lps[r]=l+1;l++;r++;}else if(l>0)l=lps[l-1];else{lps[r]=0;r++;}}
  return lps;
}
function kmpSearch(text,pattern){
  const n=text.length,m=pattern.length;if(m===0)return[0];
  const lps=buildLPS(pattern);const occ=[];let i=0,j=0;
  while(i<n){if(text[i]===pattern[j]){i++;j++;}
    if(j===m){occ.push(i-j);j=lps[j-1];}
    else if(i<n&&text[i]!==pattern[j]){if(j>0)j=lps[j-1];else i++;}}
  return occ;
}
const buildLPSImpl=buildLPS;
const kmpSearchImpl=kmpSearch;

