function rabinKarpSearch(text,pattern){
  const n=text.length,m=pattern.length;if(m>n)return[];
  const BASE=31,MOD=1e9+7;let highPow=1;
  for(let i=0;i<m-1;i++)highPow=(highPow*BASE)%MOD;
  let patHash=0,winHash=0;
  for(let i=0;i<m;i++){patHash=(patHash*BASE+pattern.charCodeAt(i))%MOD;winHash=(winHash*BASE+text.charCodeAt(i))%MOD;}
  const results=[];
  for(let i=0;i<=n-m;i++){
    if(winHash===patHash&&text.slice(i,i+m)===pattern)results.push(i);
    if(i<n-m){winHash=(winHash-text.charCodeAt(i)*highPow%MOD+MOD)%MOD;winHash=(winHash*BASE+text.charCodeAt(i+m))%MOD;}
  }
  return results;
}
const rabinKarpImpl=rabinKarpSearch;

