function zFunction(s){
  const n=s.length;const Z=new Array(n).fill(0);Z[0]=n;let l=0,r=0;
  for(let i=1;i<n;i++){if(i<r)Z[i]=Math.min(r-i,Z[i-l]);
    while(i+Z[i]<n&&s[Z[i]]===s[i+Z[i]])Z[i]++;
    if(i+Z[i]-1>r){l=i;r=i+Z[i]-1;}}
  return Z;
}
function zSearch(text,pattern){
  const combined=pattern+'$'+text;const Z=zFunction(combined);const m=pattern.length;
  const results=[];for(let i=m+1;i<combined.length;i++)if(Z[i]===m)results.push(i-m-1);
  return results;
}
