function buildSuffixArray(s){
  const n=s.length;const SA=Array.from({length:n},(_,i)=>i);
  SA.sort((a,b)=>{if(s.slice(a)<s.slice(b))return-1;if(s.slice(a)>s.slice(b))return 1;return 0;});
  return SA;
}
function buildLCP(s,SA){
  const n=s.length;const rank=new Array(n);
  for(let i=0;i<n;i++)rank[SA[i]]=i;
  const lcp=new Array(n).fill(0);let h=0;
  for(let i=0;i<n;i++){if(rank[i]>0){const j=SA[rank[i]-1];
    while(i+h<n&&j+h<n&&s[i+h]===s[j+h])h++;lcp[rank[i]]=h;if(h>0)h--;}}
  return lcp;
}
const buildSuffixArrayImpl=buildSuffixArray;
const buildLCPImpl=buildLCP;
function longestRepeatedSubstringImpl(s){const SA=buildSuffixArray(s);const lcp=buildLCP(s,SA);const maxLCP=Math.max(...lcp);if(maxLCP===0)return'';const idx=lcp.indexOf(maxLCP);return s.slice(SA[idx],SA[idx]+maxLCP);}

