class AhoCorasick{
  constructor(){this.root={children:{},fail:null,output:[]};}
  insert(pattern,id){let node=this.root;for(const c of pattern){if(!node.children[c])node.children[c]={children:{},fail:null,output:[]};node=node.children[c];}node.output.push(id);}
  build(){const queue=[];for(const c in this.root.children){this.root.children[c].fail=this.root;queue.push(this.root.children[c]);}
    while(queue.length){const curr=queue.shift();for(const c in curr.children){const child=curr.children[c];let fail=curr.fail;while(fail&&!fail.children[c])fail=fail.fail;child.fail=(fail&&fail.children[c]!==child)?fail.children[c]:this.root;child.output=child.output.concat(child.fail.output);queue.push(child);}}}
  search(text,patterns){const results=[];let node=this.root;for(let i=0;i<text.length;i++){const c=text[i];while(node!==this.root&&!node.children[c])node=node.fail;node=node.children[c]||this.root;for(const id of node.output)results.push({end:i,pattern:patterns[id]});}return results;}
}
function findAllPatterns(text,patterns){const ac=new AhoCorasick();patterns.forEach((p,i)=>ac.insert(p,i));ac.build();return ac.search(text,patterns).map(r=>r.pattern);}

